#!/usr/bin/env python3
"""Whole authentic actor-bound original/actualMetal Burn lifecycle panels."""
import argparse,json,re
from pathlib import Path
from PIL import Image,ImageDraw
from speed_profile_contract import sha

def run(native,metal,output):
 output.mkdir(parents=True,exist_ok=False);n=json.loads((native/'manifest.json').read_text());m=json.loads((metal/'manifest.json').read_text());assert m['status']=='pass'and len(m['frames'])==90 and m['sample_simulation_ticks']==list(range(1,91));selected=[r for r in n['rows']if r['image']];whole=Image.new('RGB',(1280,len(selected)*505));crop=Image.new('RGB',(220,len(selected)*220));detail=Image.new('RGB',(440,len(selected)*415));w=ImageDraw.Draw(whole);c=ImageDraw.Draw(crop);d=ImageDraw.Draw(detail);pairs=[]
 for row,r in enumerate(selected):
  t=r['tick'];paths=[Path(r['image']),Path(m['frames'][t-1]['path'])];hashes=[r['image_sha256'],m['frames'][t-1]['sha256']];assert[sha(p.read_bytes())for p in paths]==hashes;images=[Image.open(p).convert('RGB')for p in paths];boxes=[im.getbbox()for im in images];assert all(b is None or b[0]>0 and b[1]>0 and b[2]<640 and b[3]<480 for b in boxes);pairs.append(dict(tick=t,images=list(map(str,paths)),sha256=hashes,visible_bbox=boxes,native_draws=len(r['draws']),actor_health=r['actor']['health'],owner_flags=r['flags'],actor_state=r['actor_state'],actor_frame=r['actor_frame']))
  for col,(im,label)in enumerate(zip(images,('Original','Actual Metal'))):
   whole.paste(im,(col*640,row*505+25));w.text((col*640+4,row*505+5),f'{label} Burn tick{t}',fill='white');piece=im.crop((270,135,380,330));crop.paste(piece,(col*110,row*220+25));c.text((col*110+4,row*220+5),f'{label} {t}',fill='white');detail.paste(piece.resize((220,390),Image.Resampling.NEAREST),(col*220,row*415+25));d.text((col*220+4,row*415+5),f'{label} {t} 2xnearest',fill='white')
 for name,im in [('whole.png',whole),('fixed-crop.png',crop),('nearest2x-details.png',detail)]:im.save(output/name)
 log=(metal/'run.log').read_text();health={int(a):int(b)for a,b in re.findall(r'\[burn-phase\] tick=(\d+).*health=(\d+)',log)};errors=[dict(tick=r['tick'],native=r['actor']['health'],source=health[r['tick']])for r in n['rows']if r['tick']in health and health[r['tick']]!=r['actor']['health']];report=dict(status='awaiting_independent_review',accepted=False,type_id='0x55471bff',binary_sha256=m['binary_sha256'],panels={f:sha((output/f).read_bytes())for f in('whole.png','fixed-crop.png','nearest2x-details.png')},native_manifest_sha256=sha((native/'manifest.json').read_bytes()),metal_manifest_sha256=sha((metal/'manifest.json').read_bytes()),pairs=pairs,actual_actor_health_checks=len(health),health_errors=errors,configuration=m['scenario'],appearance_fitted=False,scope='ExactBurn publicSet/genuineAcolyte actor state14/frame0/facing96; fullownerPulse realDamage/stat/RNG 102→97; wholefire/smoke dual70pools/all8authoredvertices/all4triangles originalcustomRender/normalIlluminate/RGB565 kernel versus actualMetal90. Explicit integer/no-transition pose control originalInterpolatefalse; source currentmodernpose ownerprev14/staticframe0. ActualGetObjectMatrix source352fields separatelymatched original under this declared control. OriginalBURN_FRAME50/ramp8/lifespans, actualkill75 and blank76/90. Same640x480/camera320,320/source0,0,16; fixedROI270,135,380,330,2xnearestdetail display-only. All visiblebboxes interior. No geometry/color/phase fit; native-unusedtemp/flicker bytes notsemantic. Genericmap/world Pulse explicitlyupstream; originaldefault cachedtransition, natural actorpose/movement/caller/map/audio/device/exactpixels open.');assert not errors;(output/'manifest.json').write_text(json.dumps(report,indent=2)+'\n');print(report['status'],len(pairs),len(health),report['binary_sha256']);return report
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);p.add_argument('--metal',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();run(a.native,a.metal,a.output)
